import{Ct as e,ct as t,lt as n,q as r}from"./chunks/framework.BVmwMUcr.js";var i=JSON.parse(`{"title":"缓考申请攻略","description":"华南理工大学本科生因病或课程冲突申请缓考的条件、材料、审批、回执和重考确认流程","frontmatter":{"lang":"zh-CN","title":"缓考申请攻略","description":"华南理工大学本科生因病或课程冲突申请缓考的条件、材料、审批、回执和重考确认流程"},"headers":[],"relativePath":"learn/curricular/deferred_exam.md","filePath":"learn/curricular/deferred_exam.md","lastUpdated":1785179693000}`),a={name:`learn/curricular/deferred_exam.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /learn/curricular/deferred_exam.md for this page in Markdown format</div><h1 id="缓考申请攻略-别把缺考赌成缓考" tabindex="-1">缓考申请攻略：别把缺考赌成缓考 <a class="header-anchor" href="#缓考申请攻略-别把缺考赌成缓考" aria-label="Permalink to “缓考申请攻略：别把缺考赌成缓考”">​</a></h1><p>缓考不是“这次不去，下学期再考”，而是<strong>考试前完成书面申请并获得批准</strong>。没有办完手续就缺考，性质不是缓考，而是未经批准缺考。学校现行学籍管理办法规定，缓考适用于两类情况：</p><ul><li>因病不能参加考核，并附医院证明；</li><li>课程时间冲突，不能参加考核。</li></ul><p>申请人需要在考前向所在学院和开课学院提出书面申请，经双方学院主管教学副院长批准，才能参加下一学期初的课程重考。虽然和重考学生使用同一场考试，但成绩<strong>不按重考成绩记载</strong>。</p><div class="info custom-block"><p class="custom-block-title">实测范围</p><p>下面的线下流程来自土木与交通学院学生在 2025—2026 学年办理的两次缓考：一次因高烧，一次因 UC Berkeley 暑校开课时间与华工考试冲突。两次申请中，所在学院和开课学院都是土木与交通学院。</p><p>跨学院申请、考试当天突发疾病能否补办，没有亲测。遇到这两种情况，先找辅导员确认，不要拿本页赌学籍。</p></div><h2 id="一页执行清单" tabindex="-1">一页执行清单 <a class="header-anchor" href="#一页执行清单" aria-label="Permalink to “一页执行清单”">​</a></h2><ol><li>问辅导员拿本学期可用的缓考申请单，并确认教学秘书和盖章办公室。</li><li>微信告知任课老师：你准备申请缓考，避免被当成无故缺考。</li><li>准备能够覆盖考试时间的证明材料。</li><li>一门课填写一张申请单。</li><li>找教学秘书处理所在学院和开课学院的审批意见。</li><li>依次完成教学院长签名章、两处审批栏的学院公章和回执公章。</li><li>拍照留档，把申请单按要求交开课学院备案，并在考试前把盖章回执交给任课老师。</li><li>下一学期开学后，在教务系统完成“重考报名确认”，再查考试安排。</li></ol><h2 id="第一步-先问辅导员-不要先在网上捡表" tabindex="-1">第一步：先问辅导员，不要先在网上捡表 <a class="header-anchor" href="#第一步-先问辅导员-不要先在网上捡表" aria-label="Permalink to “第一步：先问辅导员，不要先在网上捡表”">​</a></h2><p>学校网站可以找到<a href="https://www2.scut.edu.cn/ep/2018/1102/c19008a293383/page.htm" target="_blank" rel="noreferrer">缓考申请单下载页</a>，但公开页面发布于 2018 年，申请单页脚标注的制表时间更早。更稳的做法是直接问辅导员：</p><blockquote><p>我需要申请 XX 课程缓考。请问本学期使用哪一版申请单？所在学院和开课学院的审批分别找哪位教学秘书，需要去哪些办公室盖章？</p></blockquote><p>辅导员的价值不是替你审批，而是给出当前版本和真实的办公室路线。学校表格写的是“主管教学副院长批准”，实际办理可能由授权的教学秘书处理签名章和公章。</p><h2 id="第二步-向任课老师报备" tabindex="-1">第二步：向任课老师报备 <a class="header-anchor" href="#第二步-向任课老师报备" aria-label="Permalink to “第二步：向任课老师报备”">​</a></h2><p>任课老师不是最终审批人，但必须提前知道你不是无故缺考。可以直接发：</p><blockquote><p>老师您好，我是 XX 班的 XXX，学号 XXXXX，选修您的《XX》。原定考试时间是 X 月 X 日 X 时，我因 XX 无法参加，准备按学院流程申请缓考，先向您报备。审批完成后，我会在考试前把盖章材料发给您，并递交纸质回执。</p></blockquote><p>实测中，老师通过微信口头同意即可继续办理，“主讲教师”一栏可以由学生自己填写。老师的同意是报备，不等于学院已经批准。</p><h2 id="第三步-把证明做实" tabindex="-1">第三步：把证明做实 <a class="header-anchor" href="#第三步-把证明做实" aria-label="Permalink to “第三步：把证明做实”">​</a></h2><h3 id="因病" tabindex="-1">因病 <a class="header-anchor" href="#因病" aria-label="Permalink to “因病”">​</a></h3><p>实测路径是：</p><ol><li>到校医院挂号并就诊；</li><li>请接诊医生如实开具诊断；</li><li>取得明确的医生建议，例如“建议休息 1 天”；</li><li>办理审批时出示诊断和医生建议。</li></ol><p>一次实际申请中，诊断记录了最高体温 <code>39.5℃</code> 等症状，医生建议休息 1 天。校医院当时最多只能开 1—2 天的休息建议。学院没有收走材料，但盖签名章的老师需要现场查看。</p><p>真正有用的不是“发热”两个字，而是<strong>症状记录、诊断结论和覆盖考试时间的休息建议</strong>。医生写什么必须以真实诊疗结果为准，不要指挥医生伪造措辞。</p><p>学校正式规则只要求附医院证明，并未在公开条款中限定必须是校医院，也没有规定固定模板。使用校外医院材料、需要更长休息时间或病情紧急时，先让辅导员确认材料要求。</p><h3 id="课程冲突" tabindex="-1">课程冲突 <a class="header-anchor" href="#课程冲突" aria-label="Permalink to “课程冲突”">​</a></h3><p>不要把“因事”理解成“有张机票就能缓考”。正式规则写的是<strong>课程冲突</strong>。</p><p>一次实际获批案例是：UC Berkeley 暑校在 7 月 6 日开课，华工课程在 7 月 7 日考试。申请人出示 I-20 后通过审批，没有被要求补交机票或解释为什么不能改期。这只能证明“外校课程冲突＋I-20”曾成功获批，不能推出私人旅行、旅游或普通行程冲突也会获批。</p><p>如果你的情况不是课程冲突，先把证明发给辅导员判断是否值得申请。别先买不可退的票，再逼学院替你的决策兜底。</p><h2 id="第四步-填写申请单" tabindex="-1">第四步：填写申请单 <a class="header-anchor" href="#第四步-填写申请单" aria-label="Permalink to “第四步：填写申请单”">​</a></h2><p>空白部分手写，一门课程一张，不能用一张表申请多门课程。需要填写：</p><ul><li>姓名、学号、所在学院和专业；</li><li>申请缓考课程、主讲教师；</li><li>原考试时间；</li><li>是否已了解相关规定；</li><li>申请事由；</li><li>学生签名和日期。</li></ul><p>填表前从教务系统或考试通知中核对课程名称和考试时间，不要凭简称填写。证明材料不用粘死在申请单上，但办理时必须带着原件或可核验文件。</p><h2 id="第五步-跑完审批和三处公章" tabindex="-1">第五步：跑完审批和三处公章 <a class="header-anchor" href="#第五步-跑完审批和三处公章" aria-label="Permalink to “第五步：跑完审批和三处公章”">​</a></h2><p>在所在学院和开课学院相同的实测案例中，同一位教学秘书处理了左右两个“教学院长意见”栏。顺序是：</p><ol><li>审核申请理由和证明；</li><li>填写审批意见；</li><li>盖教学院长签名章；</li><li>在“所在学院公章”和“开课学院公章”处分别盖章；</li><li>在下方“缓考回执”的“开课学院公章”处再盖一次。</li></ol><p>即使所在学院和开课学院相同，左右两栏也不能合并，整张表共需三处学院公章。签意见、盖签名章和盖学院公章可能分布在不同办公室。材料齐全且相关老师都在时，实测审批约 10 分钟；真正容易耗时的是找错办公室或负责人不在。</p><p>如果开课学院不是本学院，按“所在学院先审批、开课学院后审批”的顺序走，并提前问清两个学院的教学秘书。跨学院路线没有亲测，不要照搬土木与交通学院的办公室安排。</p><h2 id="第六步-备案、交回执、留证据" tabindex="-1">第六步：备案、交回执、留证据 <a class="header-anchor" href="#第六步-备案、交回执、留证据" aria-label="Permalink to “第六步：备案、交回执、留证据”">​</a></h2><p>申请单印刷说明要求：</p><ul><li>审批完成后，在考试前递交开课学院教务员；</li><li>上联由开课学院教务备案；</li><li>下联回执经开课学院盖章后交任课老师。</li></ul><p>实操中，如果办公室把整张申请单交还给你，不要自行猜测该裁哪一段，现场问清“学院留哪部分、老师收哪部分”。交出任何纸质材料前，拍摄一张字迹和三处公章都清晰的完整照片。</p><p>本人不方便递交时可以请同学代交，但至少做到：</p><ol><li>考试前把完整盖章版发给任课老师；</li><li>明确告诉代交人要交给谁、交哪一联；</li><li>让任课老师或代交人确认材料已经送达；</li><li>保存聊天记录和完整照片。</li></ol><p>任课老师在录入本次成绩时，会把该课程标记为“缓考”。纸质回执的作用就是让老师知道：这不是缺考。</p><h2 id="第七步-下一学期别忘了报名" tabindex="-1">第七步：下一学期别忘了报名 <a class="header-anchor" href="#第七步-下一学期别忘了报名" aria-label="Permalink to “第七步：下一学期别忘了报名”">​</a></h2><p>缓考获批只解决“这次为什么不考”，不会自动替你报名下一场。</p><p>下一学期开学后，学院会通知学生登录教务系统。操作入口是：</p><blockquote><p>报名申请 → 重考报名确认</p></blockquote><p>以 2025—2026 学年第二学期通知为例，报名从开学第一周星期三开放，到第二周星期三结束，窗口只有一周。具体日期每学期都会变化，只认当学期通知。</p><p>报名后继续查两类信息：</p><ul><li>公共课：查看本科生院或公共课开课学院发布的重考安排；</li><li>专业课：查看开课学院官网的本科生教务通知。</li></ul><p>缓考学生通常和补考、重考学生参加同一场考试，但这只是共用考试安排。经批准的缓考成绩不按重考成绩记载，课程总评仍按该课程原有考核方式计算，平时成绩不会凭空消失。</p><p>重考机会只有一次。没有在规定时间完成“重考报名确认”，或者报名后没有参加考试，之后只能重修。别把一周窗口交给记忆力：开学第一天就设提醒。</p><h2 id="四个容易翻车的误区" tabindex="-1">四个容易翻车的误区 <a class="header-anchor" href="#四个容易翻车的误区" aria-label="Permalink to “四个容易翻车的误区”">​</a></h2><ol><li><strong>“老师同意就行。”</strong> 不行。老师只是知情，最终需要两边学院批准。</li><li><strong>“同一个学院盖一个章就够了。”</strong> 不够。所在学院栏、开课学院栏和回执各有一处章。</li><li><strong>“有事都可以申请。”</strong> 不成立。公开规则写的是因病或课程冲突，其他事由是否批准由学院判断。</li><li><strong>“批完以后等通知就行。”</strong> 不行。下一学期还要在教务系统主动确认报名。</li></ol><h2 id="依据与时效" tabindex="-1">依据与时效 <a class="header-anchor" href="#依据与时效" aria-label="Permalink to “依据与时效”">​</a></h2><ul><li><a href="https://xxgk.scut.edu.cn/2021/0815/c71a3558/page.htm" target="_blank" rel="noreferrer">《华南理工大学全日制本科学生学籍管理办法（2021 年修订）》</a>第二十九、三十和三十九条：缓考适用情形、考前书面申请、双方学院审批、下一学期参加重考、不按重考成绩记载，以及缓考成绩的绩点计算。</li><li><a href="/assets/pdf/scut_undergraduate_handbook_2024.pdf#page=69">《本科生手册》</a>PDF 第 69—70 页（手册第 67—68 页）：同一办法的缓考与成绩记载条款。</li><li><a href="https://www2.scut.edu.cn/marine/2026/0116/c39453a617522/page.htm" target="_blank" rel="noreferrer">2025—2026 学年第二学期重考报名通知</a>：一周报名窗口、教务系统入口、错过报名只能重修，以及公共课和专业课安排的发布方式。</li><li><a href="https://www2.scut.edu.cn/ep/2018/1102/c19008a293383/page.htm" target="_blank" rel="noreferrer">缓考申请单下载页</a>：学校网站公开的旧版申请单，仅作备用。实际办理前应向辅导员确认当前版本。</li></ul><p>政策、表格和办公室分工可能调整。本页能替你压缩信息，不能替学院盖章。最终以当学期本科生院、开课学院和辅导员通知为准。</p>`,57)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};